//SIPS
//SIPS
import React, { useState } from "react";
import { Avatar } from "@material-ui/core";
import {
  getImgSrc,
  getCapitalize,
  getIntial,
} from "../../../utils";
import NumberFormat from "react-number-format";
import Transactions from "./ViewStudentPayment";
function ViewStudent({
  id,
  transactions,
  user,
  feetype,
  total,
  totalBill,
  balance,
  scholarship,
  monthlyFees,
  village,
  monthlyDiscounts,
  totalDiscount,
  // ========== TRANSPORT PROPS ==========
  isTransportMode,
  transportFee,
  terms,
  // ========== END ==========
}) {
  const [open, setOpen] = useState(false);
  const name =
    getCapitalize(user?.name) +
    " " +
    getIntial(user?.middlename || " ") +
    getCapitalize(user?.surname || " ");
  const fathername =
    getCapitalize(user?.guadian?.[0]?.name || " ") +
    " " +
    getCapitalize(user?.guadian?.[0]?.lastname || " ");
  const classs = user?.classID;
  const calculatedTotalDiscount = totalDiscount > 0 ? totalDiscount : (totalBill - total - balance);
  // Safe scholarship deduction calculation
  const scholarshipDeductionValue = scholarship?.percentage > 0
    ? -((scholarship.percentage / 100) *
      (monthlyFees || []).reduce(
        (sum, mf) => sum + (mf?.total || 0) - (mf?.fees?.admission || 0),
        0
      ))
    : 0;
  // Helper for vertical alignment (positive numbers get 2 spaces to align with negative "-")
  const formatValue = (val) => {
    const s = String(val);
    if (s.startsWith('-')) return s;
    return `\u00A0\u00A0${s}`;
  };
  return (
    <div className="content__container" style={{ background: "#EEF7FF" }}>
      <div
        style={{ background: "#4fb1ff" }}
        className="d-flex flex-column align-items-center p-3 text-light mb-4"
      >
        <Avatar
          src={getImgSrc(user?.profileUrl)}
          style={{ width: "100px", height: "100px" }}
        />
        <h3>{name}</h3>
        <h5>Father: {fathername || "Not Added"}</h5>
        <h5>{id} &nbsp;{classs}</h5>
        {/* Show Route in Transport Mode */}
        {isTransportMode && <h6>Route: {user?.physicalAddress || "Not selected"}</h6>}
        <button onClick={() => setOpen(true)} className="btn red__btn">
          View Transactions
        </button>
      </div>
      {/* ========== TRANSPORT TABLE (3 Columns) ========== */}
      {isTransportMode && terms && terms.length > 0 && (
        <div className="mb-4">
          <h5 style={{ color: "#4fb1ff" }}>Transport Fee Status</h5>
          <table className="table table-bordered" style={{ background: "white" }}>
            <thead>
              <tr>
                <th style={{ fontSize: "14px" }}>Month</th>
                <th style={{ fontSize: "14px" }}>Transport Fee</th>
                <th style={{ fontSize: "14px" }}>Fee Paid</th>
              </tr>
            </thead>
            <tbody>
              {terms.map(month => {
                const monthTransactions = (transactions || [])
                  .filter(t => t.fees?.term === month && t.fees?.applyTo?.all === true);
                const paidForMonth = monthTransactions.reduce((acc, t) => acc + Number(t.amount || 0), 0);
                const discountForMonth = monthTransactions.reduce((acc, t) => acc + Number(t.Discount || 0), 0);
                const feePaid = paidForMonth + discountForMonth;
                return (
                  <tr key={month}>
                    <td style={{ fontSize: "14px" }}>{month}</td>
                    <td style={{ fontSize: "14px" }}>
                      <NumberFormat value={transportFee || 0} displayType="text" thousandSeparator={true} />
                    </td>
                    <td style={{ fontSize: "14px" }}>
                      <NumberFormat value={feePaid} displayType="text" thousandSeparator={true} renderText={(value) => formatValue(value)} />
                    </td>
                  </tr>
                );
              })}
              {/* Summary Rows */}
              <tr>
                <td style={{ fontSize: "14px" }} colSpan="2"><strong>TOTAL BILL</strong></td>
                <td style={{ fontSize: "14px" }}>
                  <strong><NumberFormat value={totalBill || 0} displayType="text" thousandSeparator={true} renderText={(value) => formatValue(value)} /></strong>
                </td>
              </tr>
              <tr>
                <td style={{ fontSize: "14px" }} colSpan="2">TOTAL AMOUNT PAID</td>
                <td style={{ fontSize: "14px" }}>
                  <NumberFormat value={-(total || 0)} displayType="text" thousandSeparator={true} />
                </td>
              </tr>
              {/* Calculate Transport Discount */}
              {(() => {
                const transportDiscount = (transactions || [])
                  .filter(t => terms.includes(t.fees?.term) && t.fees?.applyTo?.all === true)
                  .reduce((acc, t) => acc + Number(t.Discount || 0), 0);
                return transportDiscount > 0 ? (
                  <tr>
                    <td style={{ fontSize: "14px" }} colSpan="2">TOTAL DISCOUNT</td>
                    <td style={{ fontSize: "14px" }}>
                      <NumberFormat value={-transportDiscount} displayType="text" thousandSeparator={true} />
                    </td>
                  </tr>
                ) : null;
              })()}
              <tr>
                <td style={{ fontSize: "14px" }} colSpan="2"><strong>BALANCE</strong></td>
                <td style={{ fontSize: "14px" }}>
                  <strong><NumberFormat value={balance || 0} displayType="text" thousandSeparator={true} renderText={(value) => formatValue(value)} /></strong>
                </td>
              </tr>
            </tbody>
          </table>
        </div>
      )}
      {/* ========== END TRANSPORT TABLE ========== */}
      {/* ========== INSTALLMENT TABLE (Only when NOT in transport mode) ========== */}
      {!isTransportMode && (
        <table className="table table-bordered" style={{ background: "white" }}>
          <thead>
            <tr>
              <th scope="col" style={{ fontSize: "14px" }}>Installments</th>
              <th scope="col" style={{ fontSize: "14px" }}>I</th>
              <th scope="col" style={{ fontSize: "14px" }}>II</th>
              <th scope="col" style={{ fontSize: "14px" }}>III</th>
              <th scope="col" style={{ fontSize: "14px" }}>IV</th>
              <th scope="col" style={{ fontSize: "14px" }}>Total</th>
            </tr>
          </thead>
          <tbody>
            {(monthlyFees || []).map((mf) => (
              <tr key={mf?.month || 'unknown'}>
                <td style={{ fontSize: "14px" }}>{mf?.month || 'N/A'}</td>
                <td style={{ fontSize: "14px" }}>
                  <NumberFormat
                    value={mf?.fees?.tution || 0}
                    displayType={"text"}
                    thousandSeparator={true}
                  />
                </td>
                <td style={{ fontSize: "14px" }}>
                  <NumberFormat
                    value={mf?.fees?.maintenance || 0}
                    displayType={"text"}
                    thousandSeparator={true}
                  />
                </td>
                <td style={{ fontSize: "14px" }}>
                  <NumberFormat
                    value={mf?.fees?.exam || 0}
                    displayType={"text"}
                    thousandSeparator={true}
                  />
                </td>
                <td style={{ fontSize: "14px" }}>
                  <NumberFormat
                    value={mf?.fees?.admission || 0}
                    displayType={"text"}
                    thousandSeparator={true}
                  />
                </td>
                <td style={{ fontSize: "14px" }}>
                  <NumberFormat value={mf?.total || 0} displayType="text" thousandSeparator={true} renderText={(value) => formatValue(value)} />
                </td>
              </tr>
            ))}
            {scholarship?.percentage > 0 && (
              <tr>
                <td style={{ fontSize: "14px" }} colSpan="5">
                  SCHOLARSHIP {scholarship?.percentage}% (excluding admission)
                </td>
                <td style={{ fontSize: "14px" }}>
                  <NumberFormat
                    value={scholarshipDeductionValue}
                    displayType={"text"}
                    thousandSeparator={true}
                  />
                </td>
              </tr>
            )}
            <tr>
              <td style={{ fontSize: "14px" }} colSpan="5">
                <strong>TOTAL BILL</strong>
              </td>
              <td style={{ fontSize: "14px" }}>
                <strong>
                  <NumberFormat value={totalBill || 0} displayType="text" thousandSeparator={true} renderText={(value) => formatValue(value)} />
                </strong>
              </td>
            </tr>
            <tr>
              <td style={{ fontSize: "14px" }} colSpan="5">
                TOTAL AMOUNT PAID
              </td>
              <td style={{ fontSize: "14px" }}>
                <NumberFormat
                  value={-(total || 0)}
                  displayType={"text"}
                  thousandSeparator={true}
                />
              </td>
            </tr>
            {calculatedTotalDiscount > 0 && (
              <tr>
                <td style={{ fontSize: "14px" }} colSpan="5">
                  TOTAL DISCOUNT
                </td>
                <td style={{ fontSize: "14px" }}>
                  <NumberFormat
                    value={-calculatedTotalDiscount}
                    displayType={"text"}
                    thousandSeparator={true}
                  />
                </td>
              </tr>
            )}
            <tr>
              <td style={{ fontSize: "14px" }} colSpan="5">
                <strong>BALANCE</strong>
              </td>
              <td style={{ fontSize: "14px" }}>
                <strong>
                  <NumberFormat value={balance || 0} displayType="text" thousandSeparator={true} renderText={(value) => formatValue(value)} />
                </strong>
              </td>
            </tr>
          </tbody>
        </table>
      )}
      {/* ========== END INSTALLMENT TABLE ========== */}
      <Transactions
        open={open}
        setOpen={setOpen}
        name={name}
        totalBill={totalBill || 0}
        totalPaid={total || 0}
        balance={balance || 0}
        transactions={transactions || []}
      />
    </div>
  );
}
export default ViewStudent;

