import React, { useState, useEffect, useRef } from "react";
function SearchStudent({
  setclassID,
  classID,
  setstudentID,
  studentOptions,
  studentID,
  year,
  setyear,
  terms,
  setterms,
  loading,
  handleSearch,
  village,
  setvillage,
  villageOptions,
  allStudents,
  studentsLoaded,
  isTransportMode,
  setIsTransportMode,
}) {
  const [showInstallments, setShowInstallments] = useState(false);
  const [searchInput, setSearchInput] = useState("");
  const [filteredStudents, setFilteredStudents] = useState([]);
  const [selectedStudent, setSelectedStudent] = useState(null);
  const [showDropdown, setShowDropdown] = useState(false);
  const [localLoading, setLocalLoading] = useState(false);
  const [error, setError] = useState("");
  const dropdownRef = useRef(null);

  const monthsList = [
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December"
  ];

  useEffect(() => {
    setterms([]);
  }, [isTransportMode]);

  // SIPS: Four quarterly installments
  const installments = [
    "Installment-I",
    "Installment-II",
    "Installment-III",
    "Installment-IV"
  ];

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setShowDropdown(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);
  // Filter students based on search input
  useEffect(() => {
    if (!searchInput.trim() || !studentsLoaded) {
      setFilteredStudents([]);
      setShowDropdown(false);
      return;
    }
    const input = searchInput.trim();
    const isAdmissionNumber = /^\d+$/.test(input);
    if (isAdmissionNumber) {
      const userID = `BK${input}`;
      const matched = allStudents.filter(student => student.userID === userID);
      setFilteredStudents(matched);
      setShowDropdown(matched.length > 0);
    } else {
      const searchLower = input.toLowerCase();
      const matched = allStudents.filter(student => {
        const name = (student.name || "").toLowerCase();
        const surname = (student.surname || "").toLowerCase();
        const fullName = `${name} ${surname}`.trim();
        return name.includes(searchLower) || surname.includes(searchLower) || fullName.includes(searchLower);
      });
      setFilteredStudents(matched.slice(0, 10));
      setShowDropdown(matched.length > 0);
    }
  }, [searchInput, allStudents, studentsLoaded]);
  const handleInstallmentToggle = (installment) => {
    if (terms.includes(installment)) {
      setterms(terms.filter((i) => i !== installment));
    } else {
      setterms([...terms, installment]);
    }
  };
  // Dynamic options based on mode
  const currentOptions = isTransportMode ? monthsList : installments;

  const handleSelectAllInstallments = () => {
    if (terms.length === currentOptions.length) {
      setterms([]);
    } else {
      setterms([...currentOptions]);
    }
  };
  const handleStudentSelect = (student) => {
    setSelectedStudent(student);
    setSearchInput(`${student.name} ${student.surname}`.trim());
    setShowDropdown(false);
    setError("");
    setstudentID(student.userID);
    setclassID(student.classID || "");
    setyear("2025");
  };
  const handleSearchClick = (e) => {
    e.preventDefault();
    if (!selectedStudent && searchInput.trim()) {
      const input = searchInput.trim();
      const isAdmissionNumber = /^\d+$/.test(input);
      if (isAdmissionNumber && filteredStudents.length > 0) {
        handleStudentSelect(filteredStudents[0]);
      } else if (filteredStudents.length === 1) {
        handleStudentSelect(filteredStudents[0]);
      } else if (!selectedStudent) {
        setError("Please select a student from the list");
        return;
      }
    }
    if (!selectedStudent && !searchInput.trim()) {
      setError("Please enter Admission Number or Name");
      return;
    }
    if (terms.length === 0) {
      setError("Please select at least one installment");
      return;
    }
    if (selectedStudent) {
      handleSearch(selectedStudent);
    }
  };
  const handleInputChange = (e) => {
    setSearchInput(e.target.value);
    setSelectedStudent(null);
    setError("");
  };
  const handleKeyPress = (e) => {
    if (e.key === "Enter" && !localLoading) {
      handleSearchClick(e);
    }
  };
  return (
    <div className="content__container mb-3" style={{ backgroundColor: "#EEF7FF" }}>
      <h4>Search Student</h4>
      <form action="">
        {!studentsLoaded && (
          <div className="alert alert-info">
            <small>Loading students list...</small>
          </div>
        )}
        {/* Admission No. or Name search */}
        <div className="mb-3 position-relative" ref={dropdownRef}>
          <label className="form-label">Admission No. or Name</label>
          <input
            type="text"
            className="form-control"
            placeholder="e.g. 0042 or Piyush"
            value={searchInput}
            onChange={handleInputChange}
            onKeyPress={handleKeyPress}
            onFocus={() => { if (filteredStudents.length > 0) setShowDropdown(true); }}
            style={{ backgroundColor: "#ffffff" }}
            autoFocus
          />
          {error && <small className="text-danger d-block mt-1">{error}</small>}
          {showDropdown && filteredStudents.length > 0 && (
            <div
              className="position-absolute start-0 end-0 bg-white border mt-1 shadow"
              style={{ zIndex: 1000, maxHeight: "250px", overflowY: "auto", borderRadius: "4px" }}
            >
              {filteredStudents.map((student, index) => (
                <div
                  key={student.userID || index}
                  className="p-2 border-bottom"
                  style={{ cursor: "pointer" }}
                  onMouseEnter={(e) => e.currentTarget.style.backgroundColor = "#f0f0f0"}
                  onMouseLeave={(e) => e.currentTarget.style.backgroundColor = "white"}
                  onClick={() => handleStudentSelect(student)}
                >
                  <div className="d-flex justify-content-between align-items-center">
                    <strong>{student.name} {student.surname}</strong>
                    <small className="text-muted">{student.userID}</small>
                  </div>
                  {student.classID && <small className="text-muted">Class: {student.classID}</small>}
                </div>
              ))}
            </div>
          )}
          {showDropdown && searchInput && filteredStudents.length === 0 && (
            <div className="position-absolute start-0 end-0 bg-white border mt-1 shadow p-2 text-center" style={{ zIndex: 1000 }}>
              <small className="text-muted">No students found</small>
            </div>
          )}
        </div>
        {/* SIPS: Installment dropdown */}
        <div className="mb-3">
          {/* CHANGED: Dynamic label */}
          <label className="form-label">{isTransportMode ? "Select Month" : "Installment"}</label>
          <div className="selectBox">
            <select
              style={{ backgroundColor: "#ffffff" }}
              onClick={() => setShowInstallments(!showInstallments)}
              className="form-select"
            >
              {/* CHANGED: Dynamic placeholder */}
              <option>{terms.length > 0 ? terms.join(", ") : (isTransportMode ? "Select months" : "Select installments")}</option>
            </select>
            {/* <div className="mb-3">
          <label className="form-label">Installment</label>
          <div className="selectBox">
            <select
              style={{ backgroundColor: "#ffffff" }}
              onClick={() => setShowInstallments(!showInstallments)}
              className="form-select"
            >
              <option>{terms.length > 0 ? terms.join(", ") : "Select installments"}</option>
            </select> */}
            {showInstallments && (
              <div className="showcheckboxes1 px-3 py-4" style={{ backgroundColor: "#ffffff", border: "1px solid #ccc" }}>
                <div className="form-check">
                  <input
                    className="form-check-input"
                    type="checkbox"
                    checked={terms.length === currentOptions.length}
                    onChange={handleSelectAllInstallments}
                  />
                  <label className="form-check-label">Select All</label>
                </div>
                <hr />
                {(isTransportMode ? monthsList : installments).map((item) => (
                  <div key={item} className="form-check">
                    <input
                      className="form-check-input"
                      type="checkbox"
                      checked={terms.includes(item)}
                      onChange={() => handleInstallmentToggle(item)}
                    />
                    <label className="form-check-label">{item}</label>
                  </div>
                ))}
                {/* {installments.map((inst) => (
                  <div key={inst} className="form-check">
                    <input
                      className="form-check-input"
                      type="checkbox"
                      checked={terms.includes(inst)}
                      onChange={() => handleInstallmentToggle(inst)}
                    />
                    <label className="form-check-label">{inst}</label>
                  </div>
                ))} */}
              </div>
            )}
          </div>
        </div>
        {/* SIPS: Village dropdown REMOVED */}
        {loading && (
          <div className="d-flex justify-content-center">
            <div className="spinner-border" role="status">
              <span className="visually-hidden">Loading...</span>
            </div>
          </div>
        )}
        <div className="d-flex justify-content-between align-items-center">
          <button
            onClick={handleSearchClick}
            className="btn red__btn"
            disabled={loading || localLoading || !searchInput.trim() || terms.length === 0}
          >
            {(loading || localLoading) && <div className="spinner-border spinner-border-sm me-2" role="status"></div>}
            Search
          </button>

          {/* NEW: Toggle Button */}
          <button
            type="button"
            className={`btn ${isTransportMode ? 'blue__btn' : 'green__btn'}`}
            onClick={() => setIsTransportMode(!isTransportMode)}
          >
            {isTransportMode ? "Switch to Installments" : "Switch to Transport"}
          </button>
        </div>
        {/* <div>
          <button
            onClick={handleSearchClick}
            className="btn red__btn"
            disabled={loading || localLoading || !searchInput.trim() || terms.length === 0}
          >
            {(loading || localLoading) && <div className="spinner-border spinner-border-sm me-2" role="status"></div>}
            Search
          </button>
        </div> */}
      </form>
    </div>
  );
}
export default SearchStudent;